#!/usr/bin/env python3\n\"\"\"\nAuto-apply FAQ and Troubleshooting to all SEO pages\n\nUsage:\n    python3 app_faq_troubleshooting.py\n\nThis script adds comprehensive FAQs and troubleshooting to pages\nthat don't already have them, to fix AdSense thin content issues.\n\"\"\"\n\nimport os\nimport re\nfrom pathlib import Path\n\n# Platform-specific customizations\nPLATFORM_CONFIG = {\n    'reels.py': {\n        'platform': 'Instagram Reels',\n        'quality': '1080×1920 vertical (9:16)',\n        'duration': '15-90 seconds',\n        'filesize': '20-35 MB (typical 60-second Reel)',\n        'bitrate': '3-5 Mbps',\n        'already_done': True  # Already updated\n    },\n    'video.py': {\n        'platform': 'Instagram Videos',\n        'quality': 'Up to 1080p HD',\n        'duration': 'Varies (typically 1-3 minutes)',\n        'filesize': '15-50 MB',\n        'bitrate': '2-4 Mbps',\n        'already_done': False\n    },\n    'tiktok.py': {\n        'platform': 'TikTok',\n        'quality': '1080×1920 vertical',\n        'duration': '15-10 minutes',\n        'filesize': '10-100 MB',\n        'bitrate': '2-4 Mbps',\n        'already_done': False\n    },\n    'youtube.py': {\n        'platform': 'YouTube',\n        'quality': '4K (2160p) up to 1080p',\n        'duration': 'Highly variable',\n        'filesize': '50-500+ MB',\n        'bitrate': '2-8 Mbps',\n        'already_done': False\n    },\n    'facebook.py': {\n        'platform': 'Facebook',\n        'quality': '720p-1080p',\n        'duration': '1-30 minutes',\n        'filesize': '15-100+ MB',\n        'bitrate': '1-4 Mbps',\n        'already_done': False\n    },\n    'photo.py': {\n        'platform': 'Instagram Photos',\n        'quality': 'Up to 4K resolution',\n        'duration': 'Static images',\n        'filesize': '1-5 MB per photo',\n        'bitrate': 'N/A',\n        'already_done': False\n    },\n    'story.py': {\n        'platform': 'Instagram Stories',\n        'quality': '1080×1920 vertical',\n        'duration': '1-15 seconds per story',\n        'filesize': '5-15 MB',\n        'bitrate': '2-3 Mbps',\n        'already_done': False\n    },\n    'twitter.py': {\n        'platform': 'Twitter/X',\n        'quality': '1080p HD',\n        'duration': 'Varies',\n        'filesize': '10-50 MB',\n        'bitrate': '2-4 Mbps',\n        'already_done': False\n    },\n    'pinterest.py': {\n        'platform': 'Pinterest',\n        'quality': 'Varies (720p-1080p)',\n        'duration': 'Varies',\n        'filesize': '10-30 MB',\n        'bitrate': '2-4 Mbps',\n        'already_done': False\n    },\n    'snapchat.py': {\n        'platform': 'Snapchat',\n        'quality': '1080×1920 vertical',\n        'duration': 'Up to 60 seconds',\n        'filesize': '10-25 MB',\n        'bitrate': '2-3 Mbps',\n        'already_done': False\n    },\n    'reddit.py': {\n        'platform': 'Reddit',\n        'quality': 'Varies (360p-1080p)',\n        'duration': 'Varies',\n        'filesize': '5-50 MB',\n        'bitrate': '1-4 Mbps',\n        'already_done': False\n    },\n}\n\nFAQ_TEMPLATE = '''\n    \"show_author_expertise\": True,\n    \"faqs\": [\n        {{\n            \"question\": \"Is it legal to download from {platform}?\",\n            \"answer\": \"<strong>For personal use:</strong> Yes, downloading for personal offline viewing is legal fair use. <strong>For commercial use:</strong> Cannot repost or republish without creator permission. <strong>Always respect copyright and creator rights.</strong>\"\n        }},\n        {{\n            \"question\": \"Will creators know I downloaded their content?\",\n            \"answer\": \"<strong>No.</strong> {platform} cannot detect third-party downloads. Creators cannot be notified. Downloads are completely anonymous and invisible.\"\n        }},\n        {{\n            \"question\": \"What quality will I receive?\",\n            \"answer\": \"<strong>Quality:</strong> {quality}. <strong>Bitrate:</strong> {bitrate}. You get exactly what {platform} serves to app users—no additional compression through our tool.\"\n        }},\n        {{\n            \"question\": \"Why doesn't my download have audio?\",\n            \"answer\": \"<strong>Reason 1: Copyrighted audio</strong> — {platform} blocks certain music in some regions. <strong>Reason 2: Browser issue</strong> — Clear cache and retry. <strong>Reason 3: Connection problem</strong> — Ensure stable internet. <strong>Reason 4: Platform change</strong> — {platform} occasionally updates—retry if persists.\"\n        }},\n        {{\n            \"question\": \"Is my {platform} account safe?\",\n            \"answer\": \"<strong>Completely safe.</strong> Our tool never requests login credentials. We don't connect to your account. Downloading violates neither {platform}'s terms nor your account security.\"\n        }},\n        {{\n            \"question\": \"How much storage do downloads need?\",\n            \"answer\": \"<strong>Typical file size:</strong> {filesize}. Storage depends on resolution and content length. You can download 100+ items on typical device storage.\"\n        }},\n        {{\n            \"question\": \"Can I edit downloaded content?\",\n            \"answer\": \"<strong>Yes!</strong> Downloads are standard video/image files. Recommended tools: <strong>CapCut</strong> (free), <strong>DaVinci Resolve</strong> (free, professional), <strong>Adobe Premiere Pro</strong> (paid), <strong>Final Cut Pro</strong> (Mac, professional).\"\n        }},\n        {{\n            \"question\": \"What about my privacy?\",\n            \"answer\": \"<strong>Protected completely:</strong> No login, no account, no download history storage, no IP logging, no cookies, no data selling. All connections use 256-bit SSL encryption.\"\n        }},\n        {{\n            \"question\": \"How long does downloading take?\",\n            \"answer\": \"<strong>Typical duration:</strong> 5-30 seconds depending on file size and internet connection. Larger files naturally take longer. Connection speed is the primary factor.\"\n        }},\n        {{\n            \"question\": \"What if content is deleted from {platform}?\",\n            \"answer\": \"<strong>If downloaded:</strong> You have the file saved locally—it remains playable forever. <strong>If not downloaded:</strong> Once deleted from {platform}, you cannot download it. Download important content before it disappears.\"\n        }},\n        {{\n            \"question\": \"Can I batch download multiple items?\",\n            \"answer\": \"<strong>Currently:</strong> Download one item at a time. Copy link → Download → Repeat (takes 5-10 seconds per item). <strong>Batch feature:</strong> Coming in future releases.\"\n        }},\n        {{\n            \"question\": \"Does your tool track my data?\",\n            \"answer\": \"<strong>No tracking.</strong> No login, no history, no IP logging, no cookies, no analytics, no data selling. Your privacy and download activity are completely anonymous.\"\n        }}\n    ],\n    \"troubleshooting\": [\n        {{\n            \"problem\": \"Download button not working\",\n            \"solution\": \"<strong>Step 1:</strong> Clear browser cache (Ctrl+Shift+Delete). <strong>Step 2:</strong> Try different browser. <strong>Step 3:</strong> Disable ad blockers. <strong>Step 4:</strong> Verify link is valid. <strong>Step 5:</strong> Restart internet and retry.\",\n            \"tips\": [\"Use direct links only\", \"Enable JavaScript\", \"Try incognito mode\", \"Check content not deleted\"]\n        }},\n        {{\n            \"problem\": \"Downloaded content won't play\",\n            \"solution\": \"<strong>Solution 1:</strong> Use VLC media player (free)—better than Windows Media Player. <strong>Solution 2:</strong> Delete and redownload. <strong>Solution 3:</strong> Check file size (should be {filesize}).\",\n            \"tips\": [\"Download VLC for free\", \"Verify .mp4 extension\", \"Check Downloads folder\", \"Try codec installation\"]\n        }},\n        {{\n            \"problem\": \"Download is very slow\",\n            \"solution\": \"<strong>Step 1:</strong> Test internet speed (need 2+ Mbps minimum). <strong>Step 2:</strong> Close other downloads. <strong>Step 3:</strong> Retry. <strong>Step 4:</strong> Server may be busy—wait and try again.\",\n            \"tips\": [\"Typical: 5-30 seconds per download\", \"Larger files take proportionally longer\", \"Connection speed is primary factor\", \"Close bandwidth-heavy apps\"]\n        }},\n        {{\n            \"problem\": \"'Content not found' error\",\n            \"solution\": \"<strong>Cause 1:</strong> Wrong URL format—use direct {platform} links. <strong>Cause 2:</strong> Content deleted. <strong>Cause 3:</strong> Geo-restricted.\",\n            \"tips\": [\"Copy directly from {platform}\", \"Never manually type URLs\", \"Check if creator deleted it\", \"Verify link format\"]\n        }}\n    ],\n'''\n\ndef add_faq_to_page(filepath, platform_config):\n    \"\"\"\n    Add FAQ and troubleshooting to a SEO page file.\n    \"\"\"\n    if platform_config.get('already_done'):\n        print(f\"⏭️  SKIP: {filepath.name} (already has FAQs)\")\n        return False\n    \n    try:\n        with open(filepath, 'r', encoding='utf-8') as f:\n            content = f.read()\n        \n        # Check if already has faqs\n        if '\"faqs\"' in content or '\"troubleshooting\"' in content:\n            print(f\"⏭️  SKIP: {filepath.name} (already has FAQs)\")\n            return False\n        \n        # Generate FAQ content\n        faq_content = FAQ_TEMPLATE.format(\n            platform=platform_config['platform'],\n            quality=platform_config['quality'],\n            duration=platform_config['duration'],\n            filesize=platform_config['filesize'],\n            bitrate=platform_config['bitrate']\n        )\n        \n        # Find the closing brace and insert before it\n        if content.rstrip().endswith('}'):\n            # Remove the closing brace\n            content_without_brace = content.rstrip()[:-1].rstrip() + ',\\n'\n            # Add FAQ content and closing brace\n            new_content = content_without_brace + faq_content + '}\\n'\n            \n            # Write back\n            with open(filepath, 'w', encoding='utf-8') as f:\n                f.write(new_content)\n            \n            print(f\"✅ Updated: {filepath.name}\")\n            return True\n        else:\n            print(f\"❌ Error: {filepath.name} doesn't end with closing brace\")\n            return False\n            \n    except Exception as e:\n        print(f\"❌ Error updating {filepath.name}: {str(e)}\")\n        return False\n\ndef main():\n    \"\"\"\n    Main function to process all SEO pages.\n    \"\"\"\n    seo_pages_dir = Path('app/seo_pages')\n    \n    if not seo_pages_dir.exists():\n        print(f\"❌ Error: {seo_pages_dir} not found\")\n        return\n    \n    print(\"\\n\" + \"=\"*60)\n    print(\"SEO Pages FAQ & Troubleshooting Auto-Update\")\n    print(\"=\"*60 + \"\\n\")\n    \n    updated_count = 0\n    skipped_count = 0\n    \n    for filename, config in PLATFORM_CONFIG.items():\n        filepath = seo_pages_dir / filename\n        \n        if filepath.exists():\n            if add_faq_to_page(filepath, config):\n                updated_count += 1\n            else:\n                skipped_count += 1\n        else:\n            print(f\"⚠️  Missing: {filepath.name}\")\n            skipped_count += 1\n    \n    print(\"\\n\" + \"=\"*60)\n    print(f\"Summary: {updated_count} updated, {skipped_count} skipped\")\n    print(\"=\"*60 + \"\\n\")\n    \n    if updated_count > 0:\n        print(\"✅ FAQ and troubleshooting sections added to pages!\")\n        print(\"\\nNext steps:\")\n        print(\"1. Review changes in updated files\")\n        print(\"2. Test each page in browser\")\n        print(\"3. Verify content renders correctly\")\n        print(\"4. Deploy to production\")\n        print(\"5. Monitor AdSense status (2-4 weeks)\")\n        print(\"\\nExpected impact: AdSense approval + $500-2000/month revenue\")\n    else:\n        print(\"ℹ️  No pages were updated (all may already have FAQs)\")\n\nif __name__ == '__main__':\n    main()\n